import 'package:dio/dio.dart';
import 'package:dio_cache_plus/dio_cache_plus.dart';

final dio = Dio();
 dio.interceptors.add(DioCachePlusInterceptor(cacheAll:false,commonCacheDuration:const Duration(minutes:5)));
final response = await dio.get('/api/data',options: Options().setCaching(enableCache:true));
